import React from 'react';
import './Home.css';
import Header from '../components/Header';
import { useEffect } from "react";
import { loadSavedTheme, setTheme } from "../theme";


const Home = () => {

    useEffect(() => {
        loadSavedTheme();
    }, []);

    const [themeName, setThemeName] = React.useState('berry');

    const displayName = themeName.charAt(0).toUpperCase() + themeName.slice(1);

    return (
        <div className='home'>
            <div className="alphabet-overlay"></div>
            <div className='rows'>
                <div className='first-row'>
                    <Header />
                </div>

                <div className='middle-row'>
                    <div className='credit'
                        onClick={() => window.open('https://doriandejesus.github.io', '_blank')}>
                        <div className="text">
                            <h3>An Application Created By:</h3>
                            <h1>Dorian De Jesus</h1>
                        </div>
                    </div>
                    <div className='practice'
                        onClick={() => window.location.href = '/fingerspelling'}>
                        <h1>Fingerspelling <br />
                        Practice</h1>
                    </div>
                    <div className='alphabet'
                        onClick={() => window.location.href = '/dictionary'}>
                        <h1>Signed <br />
                        Alphabet</h1>
                    </div>
                </div>

                <div className='last-row'>
                    <div className='educate'>
                        <h1>Education <br /> and Resources</h1>
                    </div>
                    <div className='spell'
                        onClick={() => window.location.href = '/fingerspeller'}>
                        <h1>Finger <br />
                        Speller</h1>
                    </div>
                    <div className='color'>
                        <h1>Color Theme:<br />
                        {displayName}</h1>
                        <div className='color-buttons'>
                            <button className='color-button cherry' onClick={() => { setTheme('cherry'); setThemeName('cherry'); }}></button>
                            <button className='color-button berry' onClick={() => { setTheme('berry'); setThemeName('berry'); }}></button>
                            <button className='color-button pumpkin' onClick={() => { setTheme('pumpkin'); setThemeName('pumpkin'); }}></button>
                            <button className='color-button plum' onClick={() => { setTheme('plum'); setThemeName('plum'); }}></button>
                            <button className='color-button lime' onClick={() => { setTheme('lime'); setThemeName('lime'); }}></button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Home;